{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "Under one provision, a parent must ensure the student takes the annual TCAP tests, or state-board-approved successor tests, given to public school students in the same grade or course.",
      "rationale": "Conveys the parental testing duty, with the disability exemption stated later, but does not identify § 49-10-1403(e). Because the supplied bill does not otherwise name the program, 'one provision' leaves the amendment's target unidentified."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "Students in grade 11 must also take the examination given to public school students under the cited statute.",
      "rationale": "Conveys the grade-eleven testing requirement, but does not identify § 49-10-1403(e) or its covered program. It also does not clearly extend the parent's duty to ensure testing to this examination."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "Students in kindergarten through grade 3 must take each of three approved universal reading screeners during each of the three annual testing windows.",
      "rationale": "Conveys the grades, three screeners, and annual testing windows, but does not identify § 49-10-1403(e) or its covered program, clearly assign this duty to the parent, or specify state-board approval and department-established windows."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "The student’s results must be reported to the parent under this provision.",
      "rationale": "Conveys the reporting requirement and recipient, but 'this provision' does not identify § 49-10-1403(e) or otherwise establish which program's testing results are covered."
    },
    {
      "proposition_id": "P5",
      "status": "partial",
      "summary_quote": "Students with disabilities who, according to their IEP, would have taken alternate assessments are exempt from these requirements.",
      "rationale": "Conveys the disability exemption and IEP-based eligibility, but does not identify § 49-10-1403(e) or the program to which this exemption applies."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "The bill also makes the same assessment requirements a condition of participating in the program covered by a second amended provision.",
      "rationale": "Incorporates the earlier annual TCAP requirements and conveys the participation condition, but does not identify § 49-6-2606(a)(1). The unnamed 'second amended provision' does not otherwise identify the affected program."
    },
    {
      "proposition_id": "P7",
      "status": "partial",
      "summary_quote": "The bill also makes the same assessment requirements a condition of participating in the program covered by a second amended provision.",
      "rationale": "Incorporates the earlier grade-eleven examination requirement as a participation condition, but does not identify § 49-6-2606(a)(1) or otherwise identify the program subject to that condition."
    },
    {
      "proposition_id": "P8",
      "status": "partial",
      "summary_quote": "The bill also makes the same assessment requirements a condition of participating in the program covered by a second amended provision.",
      "rationale": "Incorporates the earlier K–3 screening requirements as a participation condition, but does not identify § 49-6-2606(a)(1) or its program. The incorporated description also omits state-board approval and the department's establishment of the windows."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "The bill would take effect July 1, 2025.",
      "rationale": "States the effective date accurately and completely."
    }
  ]
}
